solution:
pub type Password = Str
  invariant: this.len() >= 8;
  invariant: this.len() <= 128;
  invariant: this.chars().any(|c| c.is_digit());
  invariant: this.chars().any(|c| c.is_uppercase());

fn main() -> Int {
  let pwd: Password = "SecurePass1";
  return pwd.len();
}
